import GELConvergenceDiagnostics
import GELObservationRef
import RFLProvenance
try:
    from typing import List, Optional
except:
    pass

class GELT(object):

    # GELT
    def __init__(
        self,
        GEL_ID = None,
        NAME = None,
        SCENARIO_ID = None,
        EMITTER_ID = None,
        TECHNIQUE = 0,
        SOLUTION_EPOCH = 0.0,
        LATITUDE_DEG = 0.0,
        LONGITUDE_DEG = 0.0,
        ALTITUDE_M = 0.0,
        ENU_COVARIANCE_M2 = None,
        ERROR_ELLIPSE_SEMI_MAJOR_M = 0.0,
        ERROR_ELLIPSE_SEMI_MINOR_M = 0.0,
        ERROR_ELLIPSE_ORIENTATION_DEG = 0.0,
        CEP50_M = 0.0,
        CEP95_M = 0.0,
        GDOP = 0.0,
        VELOCITY_EAST_M_S = 0.0,
        VELOCITY_NORTH_M_S = 0.0,
        VELOCITY_UP_M_S = 0.0,
        VELOCITY_COVARIANCE_M2_S2 = None,
        OBSERVATION_REFS = None,
        CONVERGENCE_DIAGNOSTICS = None,
        PROVENANCE = None,
        COMPUTED_AT = 0,
        PRODUCER_ID = None,
        SIGNATURE = None,
        CANONICAL_JSON_SIGNATURE = None,
    ):
        self.GEL_ID = GEL_ID  # type: Optional[str]
        self.NAME = NAME  # type: Optional[str]
        self.SCENARIO_ID = SCENARIO_ID  # type: Optional[str]
        self.EMITTER_ID = EMITTER_ID  # type: Optional[str]
        self.TECHNIQUE = TECHNIQUE  # type: int
        self.SOLUTION_EPOCH = SOLUTION_EPOCH  # type: float
        self.LATITUDE_DEG = LATITUDE_DEG  # type: float
        self.LONGITUDE_DEG = LONGITUDE_DEG  # type: float
        self.ALTITUDE_M = ALTITUDE_M  # type: float
        self.ENU_COVARIANCE_M2 = ENU_COVARIANCE_M2  # type: Optional[List[float]]
        self.ERROR_ELLIPSE_SEMI_MAJOR_M = ERROR_ELLIPSE_SEMI_MAJOR_M  # type: float
        self.ERROR_ELLIPSE_SEMI_MINOR_M = ERROR_ELLIPSE_SEMI_MINOR_M  # type: float
        self.ERROR_ELLIPSE_ORIENTATION_DEG = ERROR_ELLIPSE_ORIENTATION_DEG  # type: float
        self.CEP50_M = CEP50_M  # type: float
        self.CEP95_M = CEP95_M  # type: float
        self.GDOP = GDOP  # type: float
        self.VELOCITY_EAST_M_S = VELOCITY_EAST_M_S  # type: float
        self.VELOCITY_NORTH_M_S = VELOCITY_NORTH_M_S  # type: float
        self.VELOCITY_UP_M_S = VELOCITY_UP_M_S  # type: float
        self.VELOCITY_COVARIANCE_M2_S2 = VELOCITY_COVARIANCE_M2_S2  # type: Optional[List[float]]
        self.OBSERVATION_REFS = OBSERVATION_REFS  # type: Optional[List[GELObservationRef.GELObservationRefT]]
        self.CONVERGENCE_DIAGNOSTICS = CONVERGENCE_DIAGNOSTICS  # type: Optional[GELConvergenceDiagnostics.GELConvergenceDiagnosticsT]
        self.PROVENANCE = PROVENANCE  # type: Optional[RFLProvenance.RFLProvenanceT]
        self.COMPUTED_AT = COMPUTED_AT  # type: int
        self.PRODUCER_ID = PRODUCER_ID  # type: Optional[str]
        self.SIGNATURE = SIGNATURE  # type: Optional[List[int]]
        self.CANONICAL_JSON_SIGNATURE = CANONICAL_JSON_SIGNATURE  # type: Optional[List[int]]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpGel = GEL()
        tmpGel.Init(buf, pos)
        return cls.InitFromObj(tmpGel)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpGel):
        x = GELT()
        x._UnPack(tmpGel)
        return x

    # GELT
    def _UnPack(self, GEL):
        if GEL is None:
            return
        self.GEL_ID = GEL.GEL_ID()
        self.NAME = GEL.NAME()
        self.SCENARIO_ID = GEL.SCENARIO_ID()
        self.EMITTER_ID = GEL.EMITTER_ID()
        self.TECHNIQUE = GEL.TECHNIQUE()
        self.SOLUTION_EPOCH = GEL.SOLUTION_EPOCH()
        self.LATITUDE_DEG = GEL.LATITUDE_DEG()
        self.LONGITUDE_DEG = GEL.LONGITUDE_DEG()
        self.ALTITUDE_M = GEL.ALTITUDE_M()
        if not GEL.ENU_COVARIANCE_M2IsNone():
            if np is None:
                self.ENU_COVARIANCE_M2 = []
                for i in range(GEL.ENU_COVARIANCE_M2Length()):
                    self.ENU_COVARIANCE_M2.append(GEL.ENU_COVARIANCE_M2(i))
            else:
                self.ENU_COVARIANCE_M2 = GEL.ENU_COVARIANCE_M2AsNumpy()
        self.ERROR_ELLIPSE_SEMI_MAJOR_M = GEL.ERROR_ELLIPSE_SEMI_MAJOR_M()
        self.ERROR_ELLIPSE_SEMI_MINOR_M = GEL.ERROR_ELLIPSE_SEMI_MINOR_M()
        self.ERROR_ELLIPSE_ORIENTATION_DEG = GEL.ERROR_ELLIPSE_ORIENTATION_DEG()
        self.CEP50_M = GEL.CEP50_M()
        self.CEP95_M = GEL.CEP95_M()
        self.GDOP = GEL.GDOP()
        self.VELOCITY_EAST_M_S = GEL.VELOCITY_EAST_M_S()
        self.VELOCITY_NORTH_M_S = GEL.VELOCITY_NORTH_M_S()
        self.VELOCITY_UP_M_S = GEL.VELOCITY_UP_M_S()
        if not GEL.VELOCITY_COVARIANCE_M2_S2IsNone():
            if np is None:
                self.VELOCITY_COVARIANCE_M2_S2 = []
                for i in range(GEL.VELOCITY_COVARIANCE_M2_S2Length()):
                    self.VELOCITY_COVARIANCE_M2_S2.append(GEL.VELOCITY_COVARIANCE_M2_S2(i))
            else:
                self.VELOCITY_COVARIANCE_M2_S2 = GEL.VELOCITY_COVARIANCE_M2_S2AsNumpy()
        if not GEL.OBSERVATION_REFSIsNone():
            self.OBSERVATION_REFS = []
            for i in range(GEL.OBSERVATION_REFSLength()):
                if GEL.OBSERVATION_REFS(i) is None:
                    self.OBSERVATION_REFS.append(None)
                else:
                    gELObservationRef_ = GELObservationRef.GELObservationRefT.InitFromObj(GEL.OBSERVATION_REFS(i))
                    self.OBSERVATION_REFS.append(gELObservationRef_)
        if GEL.CONVERGENCE_DIAGNOSTICS() is not None:
            self.CONVERGENCE_DIAGNOSTICS = GELConvergenceDiagnostics.GELConvergenceDiagnosticsT.InitFromObj(GEL.CONVERGENCE_DIAGNOSTICS())
        if GEL.PROVENANCE() is not None:
            self.PROVENANCE = RFLProvenance.RFLProvenanceT.InitFromObj(GEL.PROVENANCE())
        self.COMPUTED_AT = GEL.COMPUTED_AT()
        self.PRODUCER_ID = GEL.PRODUCER_ID()
        if not GEL.SIGNATUREIsNone():
            if np is None:
                self.SIGNATURE = []
                for i in range(GEL.SIGNATURELength()):
                    self.SIGNATURE.append(GEL.SIGNATURE(i))
            else:
                self.SIGNATURE = GEL.SIGNATUREAsNumpy()
        if not GEL.CANONICAL_JSON_SIGNATUREIsNone():
            if np is None:
                self.CANONICAL_JSON_SIGNATURE = []
                for i in range(GEL.CANONICAL_JSON_SIGNATURELength()):
                    self.CANONICAL_JSON_SIGNATURE.append(GEL.CANONICAL_JSON_SIGNATURE(i))
            else:
                self.CANONICAL_JSON_SIGNATURE = GEL.CANONICAL_JSON_SIGNATUREAsNumpy()

    # GELT
    def Pack(self, builder):
        if self.GEL_ID is not None:
            GEL_ID = builder.CreateString(self.GEL_ID)
        if self.NAME is not None:
            NAME = builder.CreateString(self.NAME)
        if self.SCENARIO_ID is not None:
            SCENARIO_ID = builder.CreateString(self.SCENARIO_ID)
        if self.EMITTER_ID is not None:
            EMITTER_ID = builder.CreateString(self.EMITTER_ID)
        if self.ENU_COVARIANCE_M2 is not None:
            if np is not None and type(self.ENU_COVARIANCE_M2) is np.ndarray:
                ENU_COVARIANCE_M2 = builder.CreateNumpyVector(self.ENU_COVARIANCE_M2)
            else:
                GELStartENU_COVARIANCE_M2Vector(builder, len(self.ENU_COVARIANCE_M2))
                for i in reversed(range(len(self.ENU_COVARIANCE_M2))):
                    builder.PrependFloat64(self.ENU_COVARIANCE_M2[i])
                ENU_COVARIANCE_M2 = builder.EndVector()
        if self.VELOCITY_COVARIANCE_M2_S2 is not None:
            if np is not None and type(self.VELOCITY_COVARIANCE_M2_S2) is np.ndarray:
                VELOCITY_COVARIANCE_M2_S2 = builder.CreateNumpyVector(self.VELOCITY_COVARIANCE_M2_S2)
            else:
                GELStartVELOCITY_COVARIANCE_M2_S2Vector(builder, len(self.VELOCITY_COVARIANCE_M2_S2))
                for i in reversed(range(len(self.VELOCITY_COVARIANCE_M2_S2))):
                    builder.PrependFloat64(self.VELOCITY_COVARIANCE_M2_S2[i])
                VELOCITY_COVARIANCE_M2_S2 = builder.EndVector()
        if self.OBSERVATION_REFS is not None:
            OBSERVATION_REFSlist = []
            for i in range(len(self.OBSERVATION_REFS)):
                OBSERVATION_REFSlist.append(self.OBSERVATION_REFS[i].Pack(builder))
            GELStartOBSERVATION_REFSVector(builder, len(self.OBSERVATION_REFS))
            for i in reversed(range(len(self.OBSERVATION_REFS))):
                builder.PrependUOffsetTRelative(OBSERVATION_REFSlist[i])
            OBSERVATION_REFS = builder.EndVector()
        if self.CONVERGENCE_DIAGNOSTICS is not None:
            CONVERGENCE_DIAGNOSTICS = self.CONVERGENCE_DIAGNOSTICS.Pack(builder)
        if self.PROVENANCE is not None:
            PROVENANCE = self.PROVENANCE.Pack(builder)
        if self.PRODUCER_ID is not None:
            PRODUCER_ID = builder.CreateString(self.PRODUCER_ID)
        if self.SIGNATURE is not None:
            if np is not None and type(self.SIGNATURE) is np.ndarray:
                SIGNATURE = builder.CreateNumpyVector(self.SIGNATURE)
            else:
                GELStartSIGNATUREVector(builder, len(self.SIGNATURE))
                for i in reversed(range(len(self.SIGNATURE))):
                    builder.PrependUint8(self.SIGNATURE[i])
                SIGNATURE = builder.EndVector()
        if self.CANONICAL_JSON_SIGNATURE is not None:
            if np is not None and type(self.CANONICAL_JSON_SIGNATURE) is np.ndarray:
                CANONICAL_JSON_SIGNATURE = builder.CreateNumpyVector(self.CANONICAL_JSON_SIGNATURE)
            else:
                GELStartCANONICAL_JSON_SIGNATUREVector(builder, len(self.CANONICAL_JSON_SIGNATURE))
                for i in reversed(range(len(self.CANONICAL_JSON_SIGNATURE))):
                    builder.PrependUint8(self.CANONICAL_JSON_SIGNATURE[i])
                CANONICAL_JSON_SIGNATURE = builder.EndVector()
        GELStart(builder)
        if self.GEL_ID is not None:
            GELAddGEL_ID(builder, GEL_ID)
        if self.NAME is not None:
            GELAddNAME(builder, NAME)
        if self.SCENARIO_ID is not None:
            GELAddSCENARIO_ID(builder, SCENARIO_ID)
        if self.EMITTER_ID is not None:
            GELAddEMITTER_ID(builder, EMITTER_ID)
        GELAddTECHNIQUE(builder, self.TECHNIQUE)
        GELAddSOLUTION_EPOCH(builder, self.SOLUTION_EPOCH)
        GELAddLATITUDE_DEG(builder, self.LATITUDE_DEG)
        GELAddLONGITUDE_DEG(builder, self.LONGITUDE_DEG)
        GELAddALTITUDE_M(builder, self.ALTITUDE_M)
        if self.ENU_COVARIANCE_M2 is not None:
            GELAddENU_COVARIANCE_M2(builder, ENU_COVARIANCE_M2)
        GELAddERROR_ELLIPSE_SEMI_MAJOR_M(builder, self.ERROR_ELLIPSE_SEMI_MAJOR_M)
        GELAddERROR_ELLIPSE_SEMI_MINOR_M(builder, self.ERROR_ELLIPSE_SEMI_MINOR_M)
        GELAddERROR_ELLIPSE_ORIENTATION_DEG(builder, self.ERROR_ELLIPSE_ORIENTATION_DEG)
        GELAddCEP50_M(builder, self.CEP50_M)
        GELAddCEP95_M(builder, self.CEP95_M)
        GELAddGDOP(builder, self.GDOP)
        GELAddVELOCITY_EAST_M_S(builder, self.VELOCITY_EAST_M_S)
        GELAddVELOCITY_NORTH_M_S(builder, self.VELOCITY_NORTH_M_S)
        GELAddVELOCITY_UP_M_S(builder, self.VELOCITY_UP_M_S)
        if self.VELOCITY_COVARIANCE_M2_S2 is not None:
            GELAddVELOCITY_COVARIANCE_M2_S2(builder, VELOCITY_COVARIANCE_M2_S2)
        if self.OBSERVATION_REFS is not None:
            GELAddOBSERVATION_REFS(builder, OBSERVATION_REFS)
        if self.CONVERGENCE_DIAGNOSTICS is not None:
            GELAddCONVERGENCE_DIAGNOSTICS(builder, CONVERGENCE_DIAGNOSTICS)
        if self.PROVENANCE is not None:
            GELAddPROVENANCE(builder, PROVENANCE)
        GELAddCOMPUTED_AT(builder, self.COMPUTED_AT)
        if self.PRODUCER_ID is not None:
            GELAddPRODUCER_ID(builder, PRODUCER_ID)
        if self.SIGNATURE is not None:
            GELAddSIGNATURE(builder, SIGNATURE)
        if self.CANONICAL_JSON_SIGNATURE is not None:
            GELAddCANONICAL_JSON_SIGNATURE(builder, CANONICAL_JSON_SIGNATURE)
        GEL = GELEnd(builder)
        return GEL
